insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Até o término do prazo do art. 164, poderá o condenado requerer ao Juiz o pagamento da multa em prestações mensais, iguais e sucessivas. O Juiz, antes de decidir, poderá determinar diligências para verificar a situação econômica do condenado e, ouvido o Ministério Público, fixará o número de prestações. Se o condenado for impontual ou melhorar de situação econômica, o Juiz revogará o benefício, executando-se a multa.', '["Parcelamento em prestações mensais.","Diligências sobre a situação econômica.","Revogação por impontualidade ou melhora econômica."]'::jsonb, '["Revogação do parcelamento por impontualidade ou melhora econômica."]'::jsonb, 'O condenado parcela a multa, mas perde o benefício se atrasar.', '["Assertiva que impede o parcelamento da multa erra: é possível."]'::jsonb, '[]'::jsonb, '["Art. 164"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-169'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a pena de multa for aplicada cumulativamente com pena privativa da liberdade, enquanto esta estiver sendo executada, poderá aquela ser cobrada mediante desconto na remuneração do condenado. Se o condenado cumprir a pena privativa ou obtiver livramento condicional sem haver resgatado a multa, a cobrança far-se-á nos termos do Capítulo. O mesmo se aplica à suspensão condicional da pena.', '["Multa cumulativa pode ser descontada da remuneração durante a pena.","Após o cumprimento, cobra-se pelo procedimento comum.","Vale também no sursis."]'::jsonb, '["Cobrança após o cumprimento da pena privativa, livramento ou sursis."]'::jsonb, 'A multa cumulativa é descontada do salário do preso que trabalha.', '["Assertiva que extingue a multa com o cumprimento da pena privativa erra: ela é cobrada pelo procedimento comum."]'::jsonb, '[]'::jsonb, '["Art. 168"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-170'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

