select u.id, u.content_sha256, 'Transitada em julgado a sentença que aplicar medida de segurança, será ordenada a expedição de guia para a execução.', '["Guia para a execução da medida de segurança."]'::jsonb, '["Trânsito em julgado."]'::jsonb, 'Transitada a sentença, o juiz manda expedir a guia da medida de segurança.', '["Assertiva que dispensa a guia na medida de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 172"]'::jsonb, 'under_review', 'claude'
