insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ninguém será internado em Hospital de Custódia e Tratamento Psiquiátrico, ou submetido a tratamento ambulatorial, para cumprimento de medida de segurança, sem a guia expedida pela autoridade judiciária.', '["Sem guia, sem internação ou tratamento ambulatorial."]'::jsonb, '["Guia judicial obrigatória."]'::jsonb, 'O HCTP só interna com a guia judicial.', '["Assertiva que permite a internação sem guia judicial erra."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
