select u.id, u.content_sha256, 'Nos exames sucessivos para verificar-se a cessação da periculosidade, observar-se-á, no que lhes for aplicável, o disposto no artigo anterior.', '["Exames sucessivos seguem o procedimento do art. 176."]'::jsonb, '["Aplicação no que couber."]'::jsonb, 'A cada novo exame, repete-se o procedimento.', '["Assertiva que cria rito diferente para os exames sucessivos erra."]'::jsonb, '[]'::jsonb, '["Art. 176"]'::jsonb, 'under_review', 'claude'
