select u.id, u.content_sha256, 'Nas hipóteses de desinternação ou de liberação, conforme o art. 97, §3º, do Código Penal, aplicar-se-á o disposto nos arts. 132 e 133 da Lei, que tratam das condições do livramento condicional.', '["Desinternação ou liberação seguem os arts. 132 e 133."]'::jsonb, '["Mesmas condições do livramento."]'::jsonb, 'O desinternado fica sujeito a condições semelhantes às do livramento condicional.', '["Assertiva que isenta o desinternado de qualquer condição erra."]'::jsonb, '[]'::jsonb, '["Arts. 132 e 133"]'::jsonb, 'under_review', 'claude'
