select u.id, u.content_sha256, 'Transitada em julgado a sentença, o Juiz expedirá ordem para a desinternação ou a liberação.', '["Ordem de desinternação ou liberação após o trânsito em julgado."]'::jsonb, '["Depende do trânsito em julgado."]'::jsonb, 'Transitada a decisão, o juiz expede a ordem de desinternação.', '["Assertiva que dispensa o trânsito em julgado para a ordem de desinternação erra."]'::jsonb, '[]'::jsonb, '["Art. 178"]'::jsonb, 'under_review', 'claude'
