insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dispositivo revogado da Lei de Execução Penal, que tratava da conversão da pena de multa e foi retirado do texto vigente.', '["Dispositivo sem conteúdo vigente."]'::jsonb, '["Dispositivo revogado; não use para estudo."]'::jsonb, 'O art. 182 não tem mais regra em vigor.', '["Assertiva que aplica o art. 182 da LEP erra: o dispositivo foi revogado."]'::jsonb, '[]'::jsonb, '["Art. 181"]'::jsonb, 'under_review', 'claude'
