insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando, no curso da execução da pena privativa de liberdade, sobrevier doença mental ou perturbação da saúde mental, o Juiz, de ofício, a requerimento do Ministério Público, da Defensoria Pública ou da autoridade administrativa, poderá determinar a substituição da pena por medida de segurança.', '["Doença mental superveniente.","Substituição da pena por medida de segurança.","Legitimados: juiz, MP, Defensoria ou autoridade administrativa."]'::jsonb, '["ATUALIZAÇÃO: a Defensoria Pública foi incluída entre os legitimados."]'::jsonb, 'O condenado com doença mental superveniente tem a pena substituída por medida de segurança.', '["Assertiva que exclui a Defensoria Pública entre os legitimados a pedir a substituição erra."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-183'
