insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tratamento ambulatorial poderá ser convertido em internação se o agente revelar incompatibilidade com a medida. Nesta hipótese, o prazo mínimo de internação será de 1 ano.', '["Conversão do tratamento ambulatorial em internação.","Prazo mínimo de 1 ano."]'::jsonb, '["Prazo mínimo de 1 ano na internação convertida."]'::jsonb, 'O agente que não se adapta ao tratamento ambulatorial é internado por, no mínimo, um ano.', '["Assertiva que fixa em 3 anos o prazo mínimo da internação convertida erra: é 1 ano."]'::jsonb, '[]'::jsonb, '["Art. 175"]'::jsonb, 'under_review', 'claude'
