insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Haverá excesso ou desvio de execução sempre que algum ato for praticado além dos limites fixados na sentença, em normas legais ou regulamentares.', '["Excesso ou desvio: ato além dos limites da sentença ou das normas."]'::jsonb, '["Incidente da execução."]'::jsonb, 'Manter o preso além do prazo da sentença configura excesso de execução.', '["Assertiva que restringe o excesso de execução às penas privativas de liberdade erra."]'::jsonb, '[]'::jsonb, '["Art. 186"]'::jsonb, 'under_review', 'claude'
