insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No prazo de 6 meses, a contar da publicação da Lei, serão editadas as normas complementares ou regulamentares necessárias à eficácia dos dispositivos não autoaplicáveis. Dentro do mesmo prazo, as Unidades Federativas, em convênio com o Ministério da Justiça, projetarão a adaptação, construção e equipamento de estabelecimentos e serviços penais, e será providenciada a aquisição ou desapropriação de prédios para casas de albergados. O prazo poderá ser ampliado pelo Conselho Nacional, e o descumprimento injustificado implicará a suspensão de ajuda financeira da União.', '["Prazo de 6 meses para normas complementares.","Adaptação e construção de estabelecimentos.","Prorrogação pelo Conselho Nacional.","Suspensão de ajuda financeira em caso de descumprimento."]'::jsonb, '["Dispositivo transitório.","Descumprimento injustificado suspende a ajuda financeira federal."]'::jsonb, 'O Estado que não adapta seus presídios perde a ajuda financeira da União.', '["Assertiva que fixa em 1 ano o prazo do art. 203 erra: são 6 meses."]'::jsonb, '[]'::jsonb, '["Art. 204"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-203'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei entra em vigor concomitantemente com a lei de reforma da Parte Geral do Código Penal, revogadas as disposições em contrário, especialmente a Lei nº 3.274, de 2 de outubro de 1957.', '["Vigência junto com a reforma da Parte Geral do Código Penal.","Revoga a Lei nº 3.274, de 1957."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'A LEP e a reforma do Código Penal passaram a valer juntas.', '["Assertiva que prevê vigência imediata na data da publicação erra: foi concomitante com a reforma do Código Penal."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-204'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lei cria um sistema de proteção integral voltado a todas as crianças e adolescentes, tratando-os como sujeitos de direitos e não como meros objetos de tutela.', '["Doutrina da proteção integral.","Criança e adolescente como sujeitos de direitos."]'::jsonb, '["Proteção INTEGRAL é a ideia central do Estatuto."]'::jsonb, 'Toda política pública para a infância parte da proteção integral prevista no Estatuto.', '["Assertiva que restringe a proteção integral apenas a crianças em situação irregular erra."]'::jsonb, '[{"termo":"Proteção integral","significado":"Garantia de todos os direitos fundamentais a toda criança e adolescente."}]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Criança é quem tem até doze anos incompletos; adolescente é quem tem de doze a dezoito anos. Em casos expressos em lei, o Estatuto aplica-se, excepcionalmente, a quem tem entre dezoito e vinte e um anos.', '["Criança: até doze anos incompletos.","Adolescente: doze a dezoito anos.","Aplicação excepcional entre dezoito e vinte e um anos."]'::jsonb, '["O critério é cronológico e a idade de doze anos já é de adolescente.","A extensão até vinte e um anos só vale nos casos expressos em lei, como a medida socioeducativa."]'::jsonb, 'Quem tem doze anos completos já é adolescente para o Estatuto.', '["Assertiva que define criança como quem tem até doze anos completos erra: são doze anos incompletos."]'::jsonb, '[]'::jsonb, '["Art. 121, §5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crianças e adolescentes têm todos os direitos fundamentais da pessoa humana, além da proteção integral, com oportunidades para se desenvolverem física, mental, moral, espiritual e socialmente em liberdade e dignidade. Esses direitos valem para todos, sem discriminação alguma.', '["Direitos fundamentais plenos.","Desenvolvimento integral em liberdade e dignidade.","Aplicação sem discriminação."]'::jsonb, '["O rol de não discriminação é amplo e inclui deficiência, etnia e condição econômica."]'::jsonb, 'Uma criança de família pobre tem os mesmos direitos de qualquer outra.', '["Assertiva que condiciona os direitos à situação familiar da criança erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever da família, da comunidade, da sociedade e do poder público garantir, com absoluta prioridade, os direitos da criança e do adolescente, como vida, saúde, educação, convivência familiar e comunitária. A prioridade compreende receber proteção e socorro em primeiro lugar, precedência de atendimento, preferência nas políticas sociais e destinação privilegiada de recursos públicos.', '["Dever de família, comunidade, sociedade e poder público.","Absoluta prioridade.","Primazia de socorro, precedência de atendimento, preferência em políticas e recursos privilegiados."]'::jsonb, '["A prioridade é ABSOLUTA e vem do texto constitucional.","O dever é compartilhado, não só do Estado."]'::jsonb, 'Em uma emergência, a criança deve ser socorrida em primeiro lugar.', '["Assertiva que atribui o dever de garantir os direitos apenas ao poder público erra."]'::jsonb, '[{"termo":"Absoluta prioridade","significado":"Preferência incondicional da criança e do adolescente em atendimento e recursos."}]'::jsonb, '["Constituição Federal, art. 227"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma criança ou adolescente pode ser vítima de negligência, discriminação, exploração, violência, crueldade ou opressão, e qualquer atentado, por ação ou omissão, será punido na forma da lei. A conduta que ofende direito fundamental, inclusive o abandono afetivo, é ilícita e gera reparação de danos.', '["Vedação de negligência, discriminação, exploração, violência, crueldade e opressão.","Punição por ação ou omissão.","Reparação de danos, inclusive por abandono afetivo."]'::jsonb, '["ATUALIZAÇÃO: o parágrafo único, que inclui o abandono afetivo, foi acrescentado por lei posterior.","A omissão também é punida."]'::jsonb, 'O pai que abandona afetivamente o filho pode ser obrigado a reparar danos.', '["Assertiva que isenta de reparação o abandono afetivo erra: ele está expressamente incluído."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na interpretação do Estatuto, deve-se levar em conta os fins sociais da lei, as exigências do bem comum, os direitos e deveres individuais e coletivos e a condição peculiar da criança e do adolescente como pessoas em desenvolvimento.', '["Interpretação teleológica.","Condição peculiar de pessoa em desenvolvimento."]'::jsonb, '["A condição de pessoa em desenvolvimento orienta toda a interpretação."]'::jsonb, 'O juiz decide considerando que o adolescente ainda está se desenvolvendo.', '["Assertiva que manda interpretar o Estatuto apenas pela letra da lei erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito à proteção da vida e da saúde por meio de políticas sociais públicas que permitam o nascimento e o desenvolvimento sadio e harmonioso, em condições dignas de existência.', '["Direito à vida e à saúde.","Políticas sociais públicas.","Desenvolvimento sadio e harmonioso."]'::jsonb, '["Efetivação por políticas públicas, não só por assistência individual."]'::jsonb, 'Programas de pré-natal e vacinação concretizam esse direito.', '["Assertiva que afasta o dever de políticas públicas para a saúde infantil erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado a todas as mulheres o acesso aos programas e políticas de saúde da mulher e de planejamento reprodutivo e, às gestantes, nutrição adequada, atenção humanizada à gravidez, ao parto e ao puerpério e atendimento pré-natal, perinatal e pós-natal integral no Sistema Único de Saúde. O pré-natal é feito por profissionais da atenção primária, e a gestante tem direito de opção quanto ao estabelecimento do parto.', '["Acesso a políticas de saúde da mulher e planejamento reprodutivo.","Atendimento pré-natal, perinatal e pós-natal no SUS.","Direito de opção da mulher quanto ao local do parto."]'::jsonb, '["ATUALIZAÇÃO: o artigo foi ampliado por leis posteriores sobre parto humanizado e atendimento à gestante."]'::jsonb, 'A gestante vinculada a uma maternidade pode, ainda assim, exercer o direito de opção.', '["Assertiva que restringe o atendimento pré-natal à rede particular erra: é assegurado no SUS."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituída a Semana Nacional de Prevenção da Gravidez na Adolescência, realizada anualmente na semana que incluir o dia primeiro de fevereiro, para disseminar informações preventivas e educativas. As ações ficam a cargo do poder público, com organizações da sociedade civil, dirigidas prioritariamente aos adolescentes.', '["Semana Nacional de Prevenção da Gravidez na Adolescência.","Semana que inclui o dia primeiro de fevereiro.","Público prioritário: adolescentes."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Realizada anualmente na semana que incluir o dia primeiro de fevereiro."]'::jsonb, 'Escolas promovem palestras sobre prevenção na semana de fevereiro.', '["Assertiva que fixa a semana em dezembro erra: é a que inclui o dia primeiro de fevereiro."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-8-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público, as instituições e os empregadores devem propiciar condições adequadas ao aleitamento materno, inclusive para filhos de mães privadas de liberdade. Unidades de saúde desenvolvem ações sistemáticas de promoção e apoio, e as unidades de terapia intensiva neonatal devem ter banco ou unidade de coleta de leite humano.', '["Aleitamento materno protegido, inclusive no cárcere.","Ações sistemáticas nas unidades primárias de saúde.","Banco ou coleta de leite humano nas UTIs neonatais."]'::jsonb, '["A proteção alcança filhos de mães presas."]'::jsonb, 'A mãe presa deve ter condições para amamentar.', '["Assertiva que exclui as mães privadas de liberdade do direito ao aleitamento erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Hospitais e estabelecimentos de atenção à saúde de gestantes, públicos e particulares, têm obrigações como manter prontuários individuais por dezoito anos, identificar o recém-nascido por impressão plantar e digital, e da mãe, fazer exames de metabolismo do recém-nascido e orientar os pais, fornecer declaração de nascimento e manter alojamento conjunto.', '["Prontuários por dezoito anos.","Identificação do recém-nascido e da mãe.","Exames de metabolismo e orientação aos pais.","Declaração de nascimento e alojamento conjunto."]'::jsonb, '["Prazo de guarda do prontuário: dezoito anos.","Obrigações valem para hospitais públicos e particulares."]'::jsonb, 'A maternidade colhe a impressão plantar do bebê e a digital da mãe.', '["Assertiva que fixa em cinco anos a guarda dos prontuários erra: são dezoito anos."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado acesso integral às linhas de cuidado voltadas à saúde da criança e do adolescente pelo SUS, com equidade. A criança e o adolescente com deficiência são atendidos sem discriminação ou segregação, e o poder público fornece gratuitamente medicamentos, órteses, próteses e outras tecnologias assistivas a quem precisar.', '["Acesso integral e equitativo pelo SUS.","Atendimento sem segregação de quem tem deficiência.","Fornecimento gratuito de medicamentos e tecnologias assistivas."]'::jsonb, '["Fornecimento gratuito de medicamentos, órteses e próteses."]'::jsonb, 'A criança com deficiência recebe a prótese gratuitamente pelo SUS.', '["Assertiva que condiciona o fornecimento de medicamentos à renda da família erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado acesso a programas de saúde mental do SUS para prevenção e tratamento de agravos, com atenção psicossocial básica e especializada, de urgência e emergência e hospitalar. Os profissionais recebem formação específica e permanente para detectar sinais de risco.', '["Programas de saúde mental no SUS.","Atenção básica, especializada, de urgência e hospitalar.","Formação específica e permanente dos profissionais."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O adolescente com sinais de depressão tem direito a acompanhamento psicossocial no SUS.', '["Assertiva que exclui a saúde mental dos programas do SUS para crianças erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
