insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os estabelecimentos de atendimento à saúde devem permitir a permanência em tempo integral de um dos pais ou do responsável nos casos de internação da criança ou do adolescente. A criança e o adolescente também têm direito de visitar a mãe ou o pai internados.', '["Permanência integral de um dos pais na internação.","Direito de visitar o pai ou a mãe internados."]'::jsonb, '["Vale inclusive em unidades neonatais e de terapia intensiva."]'::jsonb, 'A mãe acompanha o filho internado na UTI neonatal.', '["Assertiva que limita a permanência dos pais ao horário de visitas erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
