insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Casos de suspeita ou confirmação de castigo físico, tratamento cruel ou degradante e maus-tratos devem ser obrigatoriamente comunicados ao Conselho Tutelar, sem prejuízo de outras providências. Gestantes ou mães que queiram entregar o filho à adoção são encaminhadas, sem constrangimento, à Justiça da Infância e da Juventude, e os serviços de saúde e assistência devem acompanhar e orientar essas situações.', '["Comunicação obrigatória ao Conselho Tutelar.","Entrega voluntária para adoção sem constrangimento.","Encaminhamento à Justiça da Infância e da Juventude."]'::jsonb, '["ATUALIZAÇÃO: os parágrafos sobre entrega para adoção vieram da Lei de Adoção.","A comunicação é OBRIGATÓRIA, mesmo na suspeita."]'::jsonb, 'O médico que suspeita de maus-tratos comunica ao Conselho Tutelar.', '["Assertiva que torna facultativa a comunicação de suspeita de maus-tratos erra."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-13'
